import os
import requests

def redact_unsafe(payload, config=None, threshold=0.7):
    config = config or {}
    api_key = config.get("api_key") or os.environ["PERSPECTIVE_API_KEY"]

    response = requests.post("https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze",
        params={"key": api_key},
        json={"comment": {"text": payload["text"]}, "languages": ["en"],
              "requestedAttributes": {"TOXICITY": {}}, "doNotStore": True}, timeout=30)
    response.raise_for_status()

    toxicity_score = response.json()["attributeScores"]["TOXICITY"]["summaryScore"]["value"]

    if toxicity_score > threshold:
        return {"original_text": payload["text"], "redacted_text": "[REDACTED]", "toxicity": toxicity_score, "is_unsafe": True}
    else:
        return {"original_text": payload["text"], "redacted_text": payload["text"], "toxicity": toxicity_score, "is_unsafe": False}

def apply_safety_threshold(moderation_result, thresholds=None):
    thresholds = thresholds or {"TOXICITY": 0.7}

    for category, threshold_value in thresholds.items():
        if category in moderation_result and moderation_result[category] > threshold_value:
            return {"decision": "DENY", "reason": f"{category} score exceeds threshold"}

    return {"decision": "ALLOW", "reason": "All scores within thresholds"}

import os

class PerspectiveClient:
    def __init__(self, api_key=None):
        self.api_key = api_key or os.environ.get("PERSPECTIVE_API_KEY")
        if not self.api_key:
            raise ValueError("PERSPECTIVE_API_KEY not found in config or environment variables.")

    def get_api_key(self):
        return self.api_key

class TextModerationRequest:
    def __init__(self, text, languages=None, attributes=None):
        self.text = text
        self.languages = languages or ["en"]
        self.attributes = attributes or {"TOXICITY": {}}

    def to_json(self):
        return {
            "comment": {"text": self.text},
            "languages": self.languages,
            "requestedAttributes": self.attributes,
            "doNotStore": True
        }

class TextModerationResult:
    def __init__(self, response_json):
        self.attribute_scores = {
            attr: score["summaryScore"]["value"]
            for attr, score in response_json.get("attributeScores", {}).items()
        }

    def get_score(self, attribute):
        return self.attribute_scores.get(attribute)

    def to_dict(self):
        return self.attribute_scores
